"""Plain-English 'what changed' bullets, generated by transparent rules.

Every statement is derived from a number shown elsewhere in the dashboard, so
each one can be traced back to the filing it came from.
"""

from __future__ import annotations

import math
from dataclasses import dataclass

from .analysis import Analysis

# How big a move must be before we call it out
TONE_DELTA = 0.05          # tone index (range -1..1)
UNC_DELTA_PCT = 0.15       # uncertainty word share, relative change
MARGIN_DELTA_BPS = 50      # margin change in basis points
HEALTH_DELTA = 3.0         # scorecard points


@dataclass
class Insight:
    area: str
    text: str
    signal: str  # "positive" | "negative" | "neutral"


def _f(x):
    try:
        v = float(x)
        return None if math.isnan(v) else v
    except (TypeError, ValueError):
        return None


def money(v: float | None) -> str:
    if v is None:
        return "n/a"
    a = abs(v)
    sign = "-" if v < 0 else ""
    if a >= 1e9:
        return f"{sign}${a / 1e9:,.1f}B"
    if a >= 1e6:
        return f"{sign}${a / 1e6:,.1f}M"
    return f"{sign}${a:,.0f}"


def pct(v: float | None, signed: bool = True, digits: int = 1) -> str:
    if v is None:
        return "n/a"
    return f"{v * 100:+.{digits}f}%" if signed else f"{v * 100:.{digits}f}%"


def _dir(v: float | None, threshold: float = 0.0) -> str:
    if v is None:
        return "neutral"
    if v > threshold:
        return "positive"
    if v < -threshold:
        return "negative"
    return "neutral"


def build_insights(a: Analysis) -> list[Insight]:
    out: list[Insight] = []
    fin = a.financials
    q = a.latest
    lbl = q.fq.label
    prev_lbl, ya_lbl = q.fq.prev().label, q.fq.year_ago().label
    if lbl not in fin.index:
        return [Insight("Data", f"Financial data for {lbl} is not yet in SEC's XBRL feed.", "neutral")]
    r = fin.loc[lbl]

    # ---- growth
    rev, yoy, qoq = _f(r["revenue"]), _f(r["revenue_yoy"]), _f(r["revenue_qoq"])
    out.append(Insight(
        "Growth",
        f"Revenue was {money(rev)} in {lbl}: {pct(yoy)} vs {ya_lbl} and {pct(qoq)} vs {prev_lbl} "
        f"(year-on-year is the fairer comparison for seasonal businesses).",
        _dir(yoy, 0.01),
    ))
    eps, eps_yoy = _f(r["eps_diluted"]), _f(r["eps_diluted_yoy"])
    if eps is not None:
        out.append(Insight("Growth", f"Diluted EPS was ${eps:.2f}, {pct(eps_yoy)} year-on-year.", _dir(eps_yoy, 0.01)))

    # ---- margins
    for col, name in (("gross_margin", "Gross margin"), ("operating_margin", "Operating margin")):
        cur = _f(r[col])
        ya = _f(fin.loc[ya_lbl, col]) if ya_lbl in fin.index else None
        if cur is None:
            continue
        if ya is not None:
            bps = (cur - ya) * 10000
            verb = "expanded" if bps > 0 else "contracted"
            sig = _dir(bps, MARGIN_DELTA_BPS)
            text = (f"{name} {verb} {abs(bps):.0f} bps year-on-year to {pct(cur, False)}."
                    if abs(bps) >= MARGIN_DELTA_BPS else f"{name} was broadly stable at {pct(cur, False)} ({bps:+.0f} bps YoY).")
            out.append(Insight("Profitability", text, sig))

    # ---- cash
    fcf_ttm, ni_ttm = _f(r.get("fcf_ttm")), _f(r.get("net_income_ttm"))
    if fcf_ttm is not None:
        conv = fcf_ttm / ni_ttm if ni_ttm else None
        out.append(Insight(
            "Cash",
            f"Trailing-12-month free cash flow was {money(fcf_ttm)}"
            + (f" ({conv:.2f}x net income)." if conv is not None else "."),
            "positive" if fcf_ttm > 0 and (conv or 0) >= 0.9 else ("negative" if fcf_ttm < 0 else "neutral"),
        ))
    nc = _f(r.get("net_cash"))
    nc_ya = _f(fin.loc[ya_lbl, "net_cash"]) if ya_lbl in fin.index else None
    if nc is not None and nc_ya is not None:
        out.append(Insight(
            "Balance sheet",
            f"Net cash (cash + securities - debt) is {money(nc)}, {'up' if nc > nc_ya else 'down'} from {money(nc_ya)} a year ago.",
            "positive" if nc > nc_ya else "negative",
        ))
    buy = _f(r.get("buybacks"))
    if buy:
        out.append(Insight("Capital return", f"Spent {money(buy)} on share buybacks this quarter.", "neutral"))

    # ---- sentiment
    st = a.sentiment_table()
    if lbl in st.index:
        t_cur = _f(st.loc[lbl, "tone_index"])
        method = "FinBERT" if a.used_finbert else "Loughran-McDonald"
        for ref_lbl, ref_name in ((prev_lbl, "last quarter"), (ya_lbl, "a year ago")):
            if ref_lbl in st.index and t_cur is not None:
                t_ref = _f(st.loc[ref_lbl, "tone_index"])
                if t_ref is None:
                    continue
                d = t_cur - t_ref
                if abs(d) < TONE_DELTA:
                    text = f"Management tone ({method}) is similar to {ref_name} ({t_cur:+.2f} vs {t_ref:+.2f})."
                else:
                    text = (f"Management tone ({method}) is {'more positive' if d > 0 else 'more cautious'} than "
                            f"{ref_name} ({t_cur:+.2f} vs {t_ref:+.2f}).")
                out.append(Insight("Sentiment", text, _dir(d, TONE_DELTA)))
        u_cur = _f(st.loc[lbl].get("mdna_unc_pct"))
        u_ya = _f(st.loc[ya_lbl].get("mdna_unc_pct")) if ya_lbl in st.index else None
        if u_cur is not None and u_ya:
            rel = (u_cur - u_ya) / u_ya
            if abs(rel) >= UNC_DELTA_PCT:
                out.append(Insight(
                    "Sentiment",
                    f"Uncertainty language in MD&A {'rose' if rel > 0 else 'fell'} {abs(rel) * 100:.0f}% vs a year ago "
                    f"({u_cur:.2f}% of words vs {u_ya:.2f}%).",
                    "negative" if rel > 0 else "positive",
                ))
        # risk factors: compare like-for-like (same quarter last year = same form type)
        w_cur = _f(st.loc[lbl].get("risk_words"))
        w_ya = _f(st.loc[ya_lbl].get("risk_words")) if ya_lbl in st.index else None
        if w_cur is not None and w_cur < 300:
            out.append(Insight("Risk", "Risk factors: the filing reports no material changes since the last annual report.", "positive"))
        elif w_cur and w_ya:
            rel = (w_cur - w_ya) / w_ya
            if abs(rel) >= 0.15:
                out.append(Insight(
                    "Risk",
                    f"The risk-factor section is {abs(rel) * 100:.0f}% {'longer' if rel > 0 else 'shorter'} than a year ago "
                    f"({int(w_cur):,} vs {int(w_ya):,} words): {'new risks may have been added' if rel > 0 else 'risk disclosure was trimmed'}.",
                    "negative" if rel > 0 else "positive",
                ))

    # ---- health
    ht = a.health_table()
    if lbl in ht.index:
        h = _f(ht.loc[lbl, "overall"])
        h_ya = _f(ht.loc[ya_lbl, "overall"]) if ya_lbl in ht.index else None
        band = q.health.get("band") if q.health else "n/a"
        txt = f"Financial health score {h:.0f}/100 ({band})" if h is not None else "Financial health score n/a"
        sig = "neutral"
        if h is not None and h_ya is not None:
            d = h - h_ya
            txt += f", {d:+.0f} points vs a year ago"
            sig = _dir(d, HEALTH_DELTA)
        if q.fscore:
            txt += f"; Piotroski F-Score {q.fscore['score']}/{q.fscore['available']}"
        out.append(Insight("Health", txt + ".", sig))
    return out


def verdict(insights: list[Insight]) -> tuple[str, str]:
    """Overall direction: count positive vs negative signals."""
    pos = sum(i.signal == "positive" for i in insights)
    neg = sum(i.signal == "negative" for i in insights)
    if pos - neg >= 3:
        return "Improving", f"{pos} positive vs {neg} negative signals"
    if neg - pos >= 3:
        return "Deteriorating", f"{neg} negative vs {pos} positive signals"
    return "Stable / mixed", f"{pos} positive vs {neg} negative signals"
